components.css:
.seg {
  display: flex;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 3px;
  gap: 2px;
}
.seg button {
  flex: 1;
  background: none;
  border: none;
  border-radius: 6px;
  padding: 7px 6px;
  font-family: 'DM Sans', sans-serif;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--txt-2);
  cursor: pointer;
  transition: background 0.18s, color 0.18s;
}
.seg button:hover {
  background: var(--hover);
  color: var(--txt);
}
.seg button.active {
  background: var(--amber);
  color: #0d0a00;
}

.toggle-componentes {
  background: var(--card-hi);
  border: 1px solid var(--border);
  border-radius: 100px;
  padding: 5px 12px;
  font-family: 'DM Sans', sans-serif;
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--txt-2);
  cursor: pointer;
  transition: background 0.15s, color 0.15s, border-color 0.15s;
  white-space: nowrap;
}
.toggle-componentes:hover {
  background: var(--hover);
  color: var(--txt);
}
.toggle-componentes.active {
  background: var(--blue-dim);
  border-color: rgba(79,142,247,.35);
  color: var(--blue);
}

.info-tip {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--border);
  color: var(--txt-2);
  font-size: 0.62rem;
  font-weight: 700;
  cursor: help;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s;
}
.info-tip:hover,
.info-tip:focus {
  background: var(--amber-dim);
  color: var(--amber);
  outline: none;
}
.info-tip .tip-bubble {
  position: absolute;
  top: calc(100% + 8px);
  left: 50%;
  transform: translateX(-50%) translateY(-4px);
  width: 220px;
  background: var(--card-hi);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 10px 12px;
  font-size: 0.73rem;
  font-weight: 400;
  line-height: 1.5;
  color: var(--txt);
  box-shadow: 0 8px 24px rgba(0,0,0,.4);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.15s, transform 0.15s;
  z-index: 20;
}
.info-tip:hover .tip-bubble,
.info-tip:focus .tip-bubble {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}

.chart-card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 20px 20px 16px;
  flex: 1;
}

.kpi-number {
  font-family: 'DM Serif Display', serif;
  font-size: 6rem;
  line-height: 1;
  letter-spacing: -0.04em;
  transition: color 0.5s ease;
  font-variant-numeric: tabular-nums;
}
.kpi-number.gain { color: var(--gain); }
.kpi-number.loss { color: var(--loss); }
.kpi-number.neutral { color: var(--txt); }

.trend-badge {
  font-size: 0.7rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 100px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-variant-numeric: tabular-nums;
}
.trend-badge.up {
  background: var(--gain-dim);
  color: var(--gain);
}
.trend-badge.down {
  background: var(--loss-dim);
  color: var(--loss);
}
.trend-badge.flat {
  background: var(--border);
  color: var(--txt-2);
}

input[type=range] {
  width: 100%;
  -webkit-appearance: none;
  appearance: none;
  height: 4px;
  border-radius: 2px;
  background: var(--border);
  outline: none;
  cursor: pointer;
}
input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: var(--amber);
  cursor: pointer;
  transition: transform 0.15s;
}
input[type=range]::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}

.counter {
  display: flex;
  align-items: center;
  gap: 0;
}
.counter button {
  width: 32px;
  height: 32px;
  background: var(--card-hi);
  border: 1px solid var(--border);
  color: var(--txt);
  font-size: 1rem;
  cursor: pointer;
  transition: background 0.15s;
  display: flex;
  align-items: center;
  justify-content: center;
}
.counter button:first-child {
  border-radius: 8px 0 0 8px;
}
.counter button:last-child {
  border-radius: 0 8px 8px 0;
}
.counter button:hover {
  background: var(--hover);
}
.counter-val {
  flex: 1;
  text-align: center;
  border: 1px solid var(--border);
  border-left: none;
  border-right: none;
  height: 32px;
  line-height: 32px;
  font-size: 0.9rem;
  font-weight: 600;
  background: var(--card);
  color: var(--txt);
}

input[type=month] {
  width: 100%;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 8px;
  padding: 8px 12px;
  font-family: 'DM Sans', sans-serif;
  font-size: 0.85rem;
  color: var(--txt);
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s;
  color-scheme: dark;
}
input[type=month]:hover,
input[type=month]:focus {
  border-color: rgba(232,184,75,.4);
}

.spinner {
  width: 36px;
  height: 36px;
  border: 2.5px solid var(--border);
  border-top-color: var(--amber);
  border-radius: 50%;
  animation: spin 0.7s linear infinite;
}
@keyframes spin {
  to { transform: rotate(360deg); }
}
